// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // use a caller that is NOT the depositor account
        address attacker = address(0xBEEF);
        vm.prank(attacker);
        // attempt to set L1 block values (attacker is blocked in reference but passes in buggy version)
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.setL1BlockValues.selector, 1, 2, 3, bytes32(uint256(4)), 5, bytes32(uint256(6)), 7, 8));
        // expected: reference reverts (ok == false), buggy version returns true
        assertTrue(!ok);
    }
}

