// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the depositor account
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

        // Call setL1BlockValues as depositor
        vm.prank(depositor);
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                uint64(1), uint64(2), uint256(3), bytes32(0), uint64(4), bytes32(0), uint256(5), uint256(6)
            )
        );

        // Assert that the call succeeds on the reference (should fail on buggy version)
        assertTrue(ok, "setL1BlockValues should succeed when called by depositor");
    }
}
